import {places,recommend,planSummary,mapsUrl} from './engine.js';
const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let category='all';let searched=false;let plan=[];let storageAvailable=true;const key='wandersea-sg-plan-v1';
try{const saved=JSON.parse(localStorage.getItem(key)||'[]');if(Array.isArray(saved))plan=[...new Set(saved.filter(id=>places.some(p=>p.id===id)))];}catch{storageAvailable=false;}
const options=()=>({area:$('#area').value,hours:Number($('#hours').value),budget:Number($('#budget').value),pace:$('#pace').value});
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3200);}
function persist(){try{localStorage.setItem(key,JSON.stringify(plan));}catch{storageAvailable=false;toast('Storage unavailable. Your plan will last for this visit only.');}$('#plan-count').textContent=plan.length;}
function renderCards(){const {intent,results}=recommend(searched?$('#intent').value:'',options(),category);$('#cards').innerHTML=results.length?results.map(p=>`<article class="place-card"><div class="card-art" style="--art:${p.color}" data-glyph="${p.glyph}" aria-hidden="true"><span class="art-label">${p.tags.includes('indoor')?'UNDER A ROOF':p.cost===0?'FREE TO EXPLORE':'A LITTLE LOCAL FLAVOR'}</span><span class="district">${p.district}</span></div><div class="card-body"><div class="card-meta"><span>${p.type}</span><span>~${p.minutes} min</span></div><h3>${p.name}</h3><p>${p.description}</p><div class="match-reason">${p.reason}</div><div class="card-bottom"><button class="detail-button" data-detail="${p.id}">Take a closer look ↗</button><button class="add-button ${plan.includes(p.id)?'added':''}" data-add="${p.id}" aria-label="${plan.includes(p.id)?'Remove':'Add'} ${p.name} ${plan.includes(p.id)?'from':'to'} day plan">${plan.includes(p.id)?'✓ In my day':'+ My day'}</button></div></div></article>`).join(''):`<div class="no-results"><h3>Let's give this plan a little more room.</h3><p>No places in this starter collection match all these filters. Try another neighborhood, a different category or a larger budget. We haven't relaxed your filters automatically.</p><button class="secondary" id="relax-area">Search all Singapore neighborhoods ↗</button></div>`;
$('#results-title').textContent=searched?'A few places for your kind of day.':'Find your corner of the city.';$('#results-subtitle').textContent=searched?'Choose a stop, check the details, and add it to your day.':'A few Singapore favorites, with room to make them your own.';$('#results-status').textContent=`${results.length} ${results.length===1?'discovery':'discoveries'} · ${intent.indoor?'Indoor venues only · ':''}${intent.free?'Free activities':`Planning allowance up to S$${intent.budget} per person`} · ${intent.hours}-hour window. ${searched?'Curated keyword matching, not a live AI response.':''}`;$('#show-all').hidden=!searched&&category==='all'&&$('#area').value==='any';}
function togglePlace(id){if(!places.some(p=>p.id===id))return;if(plan.includes(id)){plan=plan.filter(x=>x!==id);toast('Removed from your day.');}else{if(plan.length>=8){toast('Keep it manageable: up to 8 places per day.');return;}plan.push(id);toast('Added to your day. Make it yours in My day.');}persist();renderCards();renderPlan();}
function timeAt(minutes){return `${String(Math.floor(minutes/60)%24).padStart(2,'0')}:${String(minutes%60).padStart(2,'0')}`;}
function renderPlan(){let [h,m]=$('#start-time').value.split(':').map(Number);let cursor=Number.isFinite(h+m)?h*60+m:600;$('#plan-items').innerHTML=plan.length?plan.map((id,i)=>{const p=places.find(p=>p.id===id);const time=timeAt(cursor);cursor+=p.minutes+20;return `<article class="plan-item"><span class="plan-time">${time}</span><div><h3>${p.name}</h3><p>~${p.minutes} minutes · ${p.cost===0?'Free entry option':`S$${p.cost} illustrative allowance / person`}</p><div class="plan-actions"><button data-move="${i}" data-direction="-1" ${i===0?'disabled':''} aria-label="Move ${p.name} earlier">↑ Earlier</button><button data-move="${i}" data-direction="1" ${i===plan.length-1?'disabled':''} aria-label="Move ${p.name} later">↓ Later</button><a href="${mapsUrl(p)}" target="_blank" rel="noopener noreferrer">Directions ↗</a><button data-remove="${id}" aria-label="Remove ${p.name}">Remove</button></div></div></article>`;}).join(''):`<div class="empty-plan"><h3>A good day starts with one place.</h3><p>Explore the collection and tap “+ My day”.<br>Your saved stops will appear here.</p><button class="secondary" data-close>Find my first stop ↗</button></div>`;const s=planSummary(plan);$('#plan-summary').innerHTML=plan.length?`<div class="plan-totals"><b>~${Math.floor(s.minutes/60)}h ${s.minutes%60}m including placeholder transfers</b><br>S$${s.cost} illustrative activity/meal allowance per person. Transport, extra food, shopping and fees are excluded.<br>${storageAvailable?'Saved on this browser/device.':'Saved for this visit only; browser storage is unavailable.'}</div>${s.minutes>options().hours*60?'<p class="warning">This day is longer than your selected time window. Remove a stop or allow more time.</p>':''}${s.cost>options().budget?'<p class="warning">Your selected stops exceed your outing allowance per person.</p>':''}${cursor-20>=1440?'<p class="warning">This sequence runs into the next day. Start earlier or remove stops.</p>':''}`:'';$('#clear-plan').hidden=!plan.length;$('#export-plan').disabled=!plan.length;}
function openPlan(){renderPlan();$('#plan-dialog').showModal();}
function detail(id){const p=places.find(p=>p.id===id);if(!p)return;$('#detail-title').textContent=p.name;$('#detail-content').innerHTML=`<p class="detail-description">${p.description}</p><div class="detail-facts"><span>${p.district}</span><span>~${p.minutes} min visit</span><span>${p.cost===0?'Free entry option':`S$${p.cost} illustrative allowance`}</span></div><p class="fine-print">${p.note}</p><p class="fine-print">Starter editorial content · prepared 19 October 2026. No live hours or availability check. Family/pace tags are suggestions, not verified accessibility or suitability guarantees.</p><div class="detail-links" style="margin-top:20px"><a href="${p.url}" target="_blank" rel="noopener noreferrer">Official visitor information ↗</a><a href="${mapsUrl(p)}" target="_blank" rel="noopener noreferrer">Walking directions ↗</a><a href="${mapsUrl(p,'transit')}" target="_blank" rel="noopener noreferrer">MRT & bus directions ↗</a><a href="https://www.klook.com/en-SG/search/result/?query=${encodeURIComponent(p.name+' Singapore')}" target="_blank" rel="noopener noreferrer">Search Klook ↗</a><a href="https://www.grab.com/sg/transport/" target="_blank" rel="noopener noreferrer">Open Grab transport ↗</a></div><p class="fine-print">Provider search results may include different products. Confirm the exact attraction, ticket, dates and final price. These are ordinary external links, not integrated or confirmed bookings.</p><button class="primary" style="margin-top:20px" data-add="${p.id}">${plan.includes(p.id)?'Remove from my day':'Add to my day'} ↗</button>`;$('#detail-dialog').showModal();}
const info={about:{title:'A thoughtful start, not a finished concierge.',html:'<p>WanderSEA is an independent Singapore travel prototype. This beta offers a curated place collection, keyword-based matching, editable day plans, browser-local saving, a downloadable plan and external service links.</p><p>Live AI, GPS discovery, embedded maps, verified opening hours, live weather, hotel inventory, ticket prices, accounts and booking confirmations are not connected. Read the implementation guide for the route to those features.</p><p>No partnership with Google, Klook, Booking.com or Grab is claimed. Provider services and terms are separate.</p>'},privacy:{title:'Your plan, on your device.',html:'<p>Your day plan is saved in this browser’s local storage. There are no accounts, analytics, advertising trackers or server-side trip storage in this static beta. Use “Clear my day” to delete its saved stops, or clear this site’s browser data.</p><p>The skyline photo and fonts load from Unsplash and Google Fonts. Those services receive ordinary browser requests. Following provider links sends you to a separate service governed by its privacy policy; hotel dates and chosen area appear in the booking link.</p><p>Do not put passport numbers, payment details or sensitive information into the planning box. This beta matches text locally; it does not send your request to an AI provider.</p><p>This is prototype information. A business privacy notice, controller contact and documented retention/consent processes must be added before a commercial service collects personal data.</p>'},terms:{title:'A little context before you explore.',html:'<p>This prototype provides general travel suggestions. Check current hours, ticket requirements, access, suitability, weather and conditions directly with each venue.</p><p>Costs and durations are illustrative planning allowances, not offers. Transfer times in My day are placeholders, not calculated routes. Do not rely on them for timed tickets or departures.</p><p>Bookings and payments take place with external providers under their terms. An outgoing link does not reserve a room, buy a ticket or book a ride. No affiliate earnings are enabled in this beta.</p><p>Provider names are used to identify services. Artwork on discovery cards is illustrative. The app does not verify seating, step-free access, dietary requirements or real-time availability.</p>'}};
document.addEventListener('click',e=>{const target=e.target.closest('button');if(!target)return;if(target.hasAttribute('data-close')){target.closest('dialog').close();return;}if(target.dataset.prompt){$('#intent').value=target.dataset.prompt;$('#area').value='any';searched=true;category='all';updateTabs();renderCards();$('#explore').scrollIntoView();}if(target.dataset.category){category=target.dataset.category;updateTabs();renderCards();}if(target.dataset.add){togglePlace(target.dataset.add);if(target.closest('#detail-dialog'))$('#detail-dialog').close();}if(target.dataset.detail)detail(target.dataset.detail);if(target.dataset.remove)togglePlace(target.dataset.remove);if(target.dataset.move!==undefined){const i=Number(target.dataset.move),j=i+Number(target.dataset.direction);if(j>=0&&j<plan.length){[plan[i],plan[j]]=[plan[j],plan[i]];persist();renderPlan();}}if(target.dataset.dialog){const i=info[target.dataset.dialog];$('#info-title').textContent=i.title;$('#info-content').innerHTML=`<div class="dialog-copy">${i.html}</div>`;$('#info-dialog').showModal();}if(target.id==='relax-area'){$('#area').value='any';$('#intent').value='';searched=false;category='all';updateTabs();renderCards();}});
function updateTabs(){document.querySelectorAll('[data-category]').forEach(b=>{b.classList.toggle('active',b.dataset.category===category);b.setAttribute('aria-pressed',String(b.dataset.category===category));});}
$('#planner-form').addEventListener('submit',e=>{e.preventDefault();searched=true;renderCards();$('#explore').scrollIntoView();});document.querySelectorAll('.filters select').forEach(s=>s.addEventListener('change',()=>{renderCards();renderPlan();}));$('#show-all').addEventListener('click',()=>{$('#intent').value='';$('#area').value='any';$('#hours').value='3';$('#budget').value='60';$('#pace').value='balanced';category='all';searched=false;updateTabs();renderCards();});$('#plan-open').addEventListener('click',openPlan);$('#banner-plan').addEventListener('click',openPlan);$('#start-time').addEventListener('change',renderPlan);$('#clear-plan').addEventListener('click',()=>{if(!confirm('Clear all stops from your saved day?'))return;plan=[];persist();renderPlan();renderCards();toast('Your saved day has been cleared.');});
$('#export-plan').addEventListener('click',()=>{if(!plan.length)return;const s=planSummary(plan);const content=`WanderSEA — My Singapore day\n\n${plan.map((id,i)=>{const p=places.find(p=>p.id===id);return `${i+1}. ${p.name}\n~${p.minutes} minutes. ${p.note}\nDirections: ${mapsUrl(p)}\nOfficial info: ${p.url}`;}).join('\n\n')}\n\nIllustrative allowances: S$${s.cost} per person. Excludes transport and extra food.\nTimes are estimates, with 20-minute placeholder transfers. Check routes, hours and availability.\nNo bookings have been made by this app.\n`;const url=URL.createObjectURL(new Blob([content],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='my-singapore-day.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your plan is downloaded.');});
const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Singapore',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());$('#checkin').min=today;$('#checkout').min=today;$('#checkin').addEventListener('change',()=>{$('#checkout').min=$('#checkin').value||today;});$('#hotel-form').addEventListener('submit',e=>{e.preventDefault();const arrival=$('#checkin').value,departure=$('#checkout').value;if(!arrival||!departure||arrival<today||departure<=arrival){$('#hotel-error').textContent='Choose a future or current check-in and a later check-out.';return;}$('#hotel-error').textContent='';const url=new URL('https://www.booking.com/searchresults.html');url.searchParams.set('ss',$('#hotel-area').value+', Singapore');url.searchParams.set('checkin',arrival);url.searchParams.set('checkout',departure);const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener noreferrer';a.click();toast('Confirm your dates, guests and rates with Booking.com.');});
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));persist();renderCards();renderPlan();
